<?php
declare(strict_types=1);
namespace FMonitor2\YiiRuntime\Controllers;
use DomainException;use FMonitor2\Otiz\{OtizSettlementV2,OtizSettlementV2DraftBuilder,OtizSettlementV2Workbook};use Yii;use yii\filters\{AccessControl,VerbFilter};use yii\web\{ForbiddenHttpException,NotFoundHttpException,Response};
final class OtizSettlementV2Controller extends PilotController
{
 public $layout=false;public function behaviors():array{return['verbs'=>['class'=>VerbFilter::class,'actions'=>['calculation'=>['GET'],'export'=>['GET'],'create'=>['POST'],'delete'=>['POST'],'refresh'=>['POST'],'cancel'=>['POST'],'replace'=>['POST'],'legacy-payment'=>['POST'],'reverse'=>['POST'],'decision'=>['POST'],'deduction'=>['POST'],'accept'=>['POST'],'payment'=>['POST']]],'access'=>['class'=>AccessControl::class,'rules'=>[['allow'=>true,'roles'=>['otiz.manage']]],'denyCallback'=>function():void{if(!Yii::$app->user->isGuest)throw new ForbiddenHttpException();Yii::$app->response->statusCode=303;Yii::$app->response->headers->set('Location','/pilot/otiz/login');}]];}
 public function actionCalculation(int$id):string{try{$c=$this->owner()->read($id);}catch(DomainException){throw new NotFoundHttpException();}return$this->render('@app/app/YiiRuntime/Views/otiz-calculation-v2',['identity'=>Yii::$app->user->identity,'calculation'=>$c,'csrf'=>Yii::$app->request->csrfToken,'query'=>Yii::$app->request->get()]);}
 public function actionCreate():Response{$input=(new OtizSettlementV2DraftBuilder(Yii::$app->db,$this->prefix(),(string)(getenv('FMONITOR_LEGACY_TABLE_PREFIX')?:$this->prefix())))->build($this->actor(),(string)Yii::$app->request->post('reportDate'));$result=$this->owner()->createDraft($this->actor(),$input,(string)Yii::$app->request->post('operationId'));return$this->redirectTo('/pilot/otiz/calculations/'.$result['calculationId'].'?created=1');}
 public function actionDelete(int$id):Response{return$this->command($id,fn($o,$r,$op)=>$o->deleteDraft($this->actor(),$id,$r,(string)Yii::$app->request->post('reason'),$op),'deleted=1');}
 public function actionRefresh(int$id):Response{$input=(new OtizSettlementV2DraftBuilder(Yii::$app->db,$this->prefix(),(string)(getenv('FMONITOR_LEGACY_TABLE_PREFIX')?:$this->prefix())))->build($this->actor(),(string)Yii::$app->request->post('reportDate'));return$this->command($id,fn($o,$r,$op)=>$o->refreshDraft($this->actor(),$id,$r,$input,$op),'refreshed=1');}
 public function actionCancel(int$id):Response{return$this->command($id,fn($o,$r,$op)=>$o->cancel($this->actor(),$id,$r,(string)Yii::$app->request->post('reason'),$op),'cancelled=1');}
 public function actionReplace(int$id):Response{$input=(new OtizSettlementV2DraftBuilder(Yii::$app->db,$this->prefix(),(string)(getenv('FMONITOR_LEGACY_TABLE_PREFIX')?:$this->prefix())))->build($this->actor(),(string)Yii::$app->request->post('reportDate'));return$this->command($id,fn($o,$r,$op)=>$o->replace($this->actor(),$id,$r,$input,(string)Yii::$app->request->post('reason'),$op),'replaced=1');}
 public function actionReverse(int$id):Response{$calculation=(int)Yii::$app->db->createCommand("SELECT calculation_id FROM `{$this->prefix()}fm2_otiz_payment_facts` WHERE id=:id",[':id'=>$id])->queryScalar();if($calculation<1)throw new NotFoundHttpException();$this->owner()->reversePayment($this->actor(),$id,(string)Yii::$app->request->post('reason'),(string)Yii::$app->request->post('operationId'));return$this->redirectTo('/pilot/otiz/calculations/'.$calculation.'?reversed=1');}
 public function actionLegacyPayment(int$id):Response{$r=Yii::$app->response;$r->statusCode=409;$r->content='<main><p role="alert">LEGACY_PAYMENT_ROUTE_RETIRED</p></main>';return$r;}
 public function actionDecision(int$id):Response{return$this->command($id,fn($o,$r,$op)=>$o->saveDecision($this->actor(),$id,$r,(string)Yii::$app->request->post('employeeId'),(string)Yii::$app->request->post('decision'),(string)Yii::$app->request->post('reason'),$op));}
 public function actionDeduction(int$id):Response{return$this->command($id,function($o,$r,$op)use($id){try{$amount=\FMonitor\Otiz\OtizSettlementV2Math::parseRubles((string)Yii::$app->request->post('amount'));}catch(\InvalidArgumentException){throw new DomainException('INVALID_MONEY');}return$o->saveDeduction($this->actor(),$id,$r,(int)Yii::$app->request->post('objectId'),Yii::$app->request->post('employeeId')!==null&&Yii::$app->request->post('employeeId')!==''?(string)Yii::$app->request->post('employeeId'):null,$amount,(string)Yii::$app->request->post('reason'),(string)Yii::$app->request->post('document',''),$op);});}
 public function actionAccept(int$id):Response{return$this->command($id,fn($o,$r,$op)=>$o->accept($this->actor(),$id,$r,$op));}public function actionPayment(int$id):Response{return$this->command($id,fn($o,$r,$op)=>$o->markPaid($this->actor(),$id,$r,(string)Yii::$app->request->post('paymentDate'),$op),'paid=1');}
 public function actionExport(int$id):Response{try{$s=$this->owner()->read($id);}catch(DomainException){throw new NotFoundHttpException();}$mode=(string)Yii::$app->request->get('mode','history');if($mode==='payment'&&$this->admissionFor($s)!=='allow'){$r=Yii::$app->response;$r->statusCode=409;return$r;}$book=OtizSettlementV2Workbook::build(['calculation'=>['id'=>$s['calculationId'],'status'=>$s['status'],'reportDate'=>$s['reportDate'],'revision'=>$s['revision'],'rulesVersion'=>'otiz-v2','totalCents'=>$s['totalCents']],'objects'=>$s['objects'],'recipients'=>$s['recipients'],'deductions'=>$s['deductions'],'decisions'=>$s['decisions'],'mode'=>$mode,'exportedAt'=>(new \DateTimeImmutable())->format(DATE_ATOM)]);$r=Yii::$app->response;$r->format=Response::FORMAT_RAW;$r->headers->set('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');$r->headers->set('Content-Disposition','attachment; filename="'.$book['filename'].'"');$r->content=$book['bytes'];return$r;}
 private function command(int$id,callable$f,string$q='saved=1'):Response{try{$f($this->owner(),(int)Yii::$app->request->post('expectedRevision'),(string)Yii::$app->request->post('operationId'));$r=Yii::$app->response;$r->statusCode=303;$r->headers->set('Location','/pilot/otiz/calculations/'.$id.'?'.$q);return$r;}catch(DomainException$e){if($e->getMessage()==='NOT_FOUND')throw new NotFoundHttpException();$r=Yii::$app->response;$r->statusCode=in_array($e->getMessage(),['STALE_REVISION','COMPOSITION_MISMATCH','ADMISSION_UNKNOWN','SNAPSHOT_REPLACEMENT_REQUIRED'],true)?409:422;$r->content='<main><p role="alert">'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</p></main>';return$r;}}
 private function owner():OtizSettlementV2{return new OtizSettlementV2(Yii::$app->db,$this->prefix(),static fn()=>(new \DateTimeImmutable('now',new \DateTimeZone('Europe/Moscow')))->format(DATE_ATOM),fn(int$o,string$p)=>$this->admission($o));}private function admission(int$o):array{$v=Yii::$app->db->createCommand("SELECT decision,source_revision,reason_code,incident_id FROM `{$this->prefix()}fm2_otiz_admission_inputs` WHERE object_id=:o ORDER BY observed_at DESC,source_revision DESC LIMIT 1",[':o'=>$o])->queryOne();return$v===false?['decision'=>'unknown','sourceRevision'=>'missing','incidentId'=>null]:['decision'=>(string)$v['decision'],'sourceRevision'=>(string)$v['source_revision'],'incidentId'=>$v['incident_id']];}private function admissionFor(array$c):string{foreach($c['objects']as$o)if(($this->admission((int)$o['objectId'])['decision']??'unknown')!=='allow')return'blocked';return'allow';}private function redirectTo(string$path):Response{$r=Yii::$app->response;$r->statusCode=303;$r->headers->set('Location',$path);return$r;}private function actor():int{return(int)Yii::$app->user->id;}private function prefix():string{return(string)getenv('FMONITOR_PROCESS_TABLE_PREFIX');}
}
